from openai import OpenAI

client = OpenAI()
stream = client.responses.create(
    model="gpt-6-astra",
    input="Write a short poem about rain.",
    stream=True,
)

for event in stream:
    if event.type == "response.output_text.delta":
        print(event.delta, end="", flush=True)
    elif event.type == "response.completed":
        print("\n tokens:", event.response.usage.total_tokens)
    elif event.type == "error":
        print("\n stream error:", event)

from openai import OpenAI

client = OpenAI()
r = client.responses.create(
    model="gpt-6-astra",
    tools=[
        {"type": "web_search",
         "filters": {"allowed_domains": ["python.org", "docs.python.org"]}},
        {"type": "code_interpreter", "container": {"type": "auto"}},
    ],
    input="What is the latest Python release, and how many days ago was it?",
)

print(r.output_text)
for item in r.output:
    if item.type == "message":
        for part in item.content:
            for a in getattr(part, "annotations", []) or []:
                if a.type == "url_citation":
                    print("source:", a.url)

import openai
from openai import OpenAI

client = OpenAI(timeout=900.0)           # flex can be slow
STABLE = open("style_guide.txt").read()  # long, identical every call

def review(text: str):
    kwargs = dict(model="gpt-6-astra", instructions=STABLE,
                  input=f"Review this paragraph:\n{text}")   # varying part last
    try:
        return client.responses.create(service_tier="flex", **kwargs)
    except openai.RateLimitError:            # flex capacity unavailable
        return client.responses.create(service_tier="auto", **kwargs)

r = review("Our product are great.")
print(r.usage.input_tokens, r.usage.input_tokens_details.cached_tokens)

import random, time
import openai
from openai import OpenAI

client = OpenAI(max_retries=0)          # we handle retries ourselves here

def create_with_backoff(max_attempts=5, **kwargs):
    for attempt in range(max_attempts):
        try:
            raw = client.responses.with_raw_response.create(**kwargs)
            print("tokens left:", raw.headers.get("x-ratelimit-remaining-tokens"))
            return raw.parse()
        except (openai.RateLimitError, openai.InternalServerError) as e:
            wait = float(e.response.headers.get("retry-after") or 2 ** attempt)
            time.sleep(wait + random.uniform(0, 1))    # jitter
    raise RuntimeError("gave up after retries")

r = create_with_backoff(model="gpt-6-luna", input="ping")

